def factor_cyclical_pressure_atrlib(df):
    df_copy = df.copy()
    atr = talib.ATR(df_copy["high"], df_copy["low"], df_copy["close"], timeperiod=90)
    atr_change = atr / atr.shift(20) - 1
    return atr_change.fillna(0).rename('factor_cyclical_pressure_atrlib')

