def factor_sales_yield_leverage_adjusted(df):
    df_copy = df.copy()
    sales_yield = 1.0 / df_copy["ps_ttm"].replace(0, np.nan)
    safe_debt = np.clip(1.0 - df_copy["debttoassets"] / 100.0, 0.0, 1.0)
    factor = sales_yield * safe_debt
    return pd.Series(factor, index=df_copy.index, name="factor_sales_yield_leverage_adjusted")
